\set ON_ERROR_STOP on
-- Disposable local PostgreSQL only; no Supabase credentials or production data.
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN BYPASSRLS;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth TO authenticated;
GRANT EXECUTE ON FUNCTION auth.uid() TO authenticated;
CREATE TABLE public.escolas(id uuid PRIMARY KEY,nome text);
CREATE TABLE public.escola_users(escola_id uuid,user_id uuid,tenant_type text,papel text);

-- Academic SSOT fixture mirrors the existing table relationships.
CREATE TABLE public.anos_letivos(id uuid PRIMARY KEY,escola_id uuid,ativo boolean,data_inicio date,data_fim date);
CREATE TABLE public.cursos(id uuid PRIMARY KEY,escola_id uuid,nome text);
CREATE TABLE public.classes(id uuid PRIMARY KEY,escola_id uuid,ano_letivo_id uuid,nome text);
CREATE TABLE public.disciplinas_catalogo(id uuid PRIMARY KEY,escola_id uuid,nome text);
CREATE TABLE public.curso_curriculos(id uuid PRIMARY KEY,escola_id uuid,ano_letivo_id uuid,curso_id uuid,classe_id uuid,status text);
CREATE TABLE public.curso_matriz(id uuid PRIMARY KEY,escola_id uuid,curso_curriculo_id uuid,curso_id uuid,classe_id uuid,disciplina_id uuid,ativo boolean,periodos_ativos integer[]);
CREATE TABLE public.periodos_letivos(escola_id uuid,ano_letivo_id uuid,tipo text,numero integer);
CREATE TABLE public.turmas(id uuid PRIMARY KEY,escola_id uuid,ano_letivo_id uuid,classe_id uuid,curso_id uuid);
CREATE TABLE public.professores(id uuid PRIMARY KEY,escola_id uuid,profile_id uuid);
CREATE TABLE public.turma_disciplinas(escola_id uuid,turma_id uuid,curso_matriz_id uuid,professor_id uuid,periodos_ativos integer[]);
CREATE TABLE public.turma_disciplinas_professores(escola_id uuid,turma_id uuid,disciplina_id uuid,professor_id uuid);

-- Nominal print reads through authenticated RLS (including campus restrictions).
ALTER TABLE public.turmas ADD COLUMN session_id uuid,ADD COLUMN nome text,ADD COLUMN letra text,ADD COLUMN turno text,ADD COLUMN sala text;
UPDATE public.turmas SET session_id=ano_letivo_id,nome='ESG-8ª Classe-M-Z',letra='A',turno='M',sala='12';
CREATE TABLE public.alunos(id uuid PRIMARY KEY,escola_id uuid,nome text,nome_completo text,numero_processo text,deleted_at timestamptz);
CREATE TABLE public.matriculas(id uuid PRIMARY KEY,escola_id uuid,session_id uuid,turma_id uuid,aluno_id uuid,ativo boolean,status text,numero_chamada integer);
 CASE WHEN n=46 THEN '80000000-0000-4000-8000-000000000002'::uuid WHEN n=47 THEN '80000000-0000-4000-8000-000000000003'::uuid ELSE '80000000-0000-4000-8000-000000000001'::uuid END,
 ('a0000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,n<>44,CASE WHEN n=43 THEN 'cancelada' ELSE 'ativa' END,n FROM generate_series(1,47) n;
GRANT SELECT ON public.turmas,public.turma_disciplinas,public.curso_matriz,public.curso_curriculos,public.cursos,public.matriculas,public.alunos TO authenticated;
ALTER TABLE public.turmas ENABLE ROW LEVEL SECURITY;
CREATE POLICY fixture_campus_scope ON public.turmas FOR SELECT TO authenticated USING (id<>'80000000-0000-4000-8000-000000000003');


-- Synthetic regime fixture; production uses the actual canonical resolver.
ALTER TABLE public.turmas ADD COLUMN fixture_escala text DEFAULT 'quantitativa_secundario';
CREATE FUNCTION public.resolve_regime_academico(p_turma_id uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('escala',fixture_escala) FROM public.turmas WHERE id=p_turma_id $$;

-- Existing production audit sink: synthetic fixture only, no extra production table.
CREATE TABLE public.profiles(user_id uuid PRIMARY KEY);
CREATE TABLE public.audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,escola_id uuid,user_id uuid REFERENCES public.profiles(user_id),actor_id uuid,acao text,tabela text,registro_id text,action text,entity text,entity_id text,details jsonb);
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.audit_logs FROM PUBLIC,anon,authenticated,service_role;
